import sys
import json
import numpy as np
import pandas as pd


def fnum(x):
    """Convert to a plain python float, rounding handled by caller."""
    return float(x)


def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTAL level facts ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(fnum(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(fnum(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": round(fnum(total_rev_ly), 2),
        "formula": "sum(Revenue_LY)"
    })

    if pd.notna(total_rev_lw) and total_rev_lw != 0:
        wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(fnum(wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if pd.notna(total_rev_ly) and total_rev_ly != 0:
        yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(fnum(yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(fnum(total_units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(fnum(total_units_lw), 2),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(fnum(total_orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(fnum(total_orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    # ---------- Per-entity facts, ordered by Rank ----------
    if 'Rank' in df.columns:
        df_sorted = df.sort_values('Rank', na_position='last')
    else:
        df_sorted = df

    for _, row in df_sorted.iterrows():
        ent = row['Entity']

        if pd.notna(row.get('Revenue_TW')):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "TW",
                "value": round(fnum(row['Revenue_TW']), 2),
                "formula": "Revenue_TW"
            })

        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": round(fnum(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": ent, "metric": "rank", "period": "TW",
                "value": round(fnum(row['Rank']), 1),
                "formula": "Rank"
            })

    # ---------- Biggest WoW / YoY movers ----------
    if 'WoW_Pct' in df.columns:
        valid_wow = df.dropna(subset=['WoW_Pct'])
        if not valid_wow.empty:
            top_wow = valid_wow.loc[valid_wow['WoW_Pct'].idxmax()]
            facts.append({
                "entity": top_wow['Entity'], "metric": "revenue", "period": "WoW",
                "value": round(fnum(top_wow['WoW_Pct']), 1),
                "formula": "WoW_Pct (largest week-over-week riser)"
            })
            bottom_wow = valid_wow.loc[valid_wow['WoW_Pct'].idxmin()]
            facts.append({
                "entity": bottom_wow['Entity'], "metric": "revenue", "period": "WoW",
                "value": round(fnum(bottom_wow['WoW_Pct']), 1),
                "formula": "WoW_Pct (largest week-over-week faller)"
            })

    if 'YoY_Pct' in df.columns:
        valid_yoy = df.dropna(subset=['YoY_Pct'])
        if not valid_yoy.empty:
            top_yoy = valid_yoy.loc[valid_yoy['YoY_Pct'].idxmax()]
            facts.append({
                "entity": top_yoy['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(fnum(top_yoy['YoY_Pct']), 1),
                "formula": "YoY_Pct (largest year-over-year riser)"
            })
            bottom_yoy = valid_yoy.loc[valid_yoy['YoY_Pct'].idxmin()]
            facts.append({
                "entity": bottom_yoy['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(fnum(bottom_yoy['YoY_Pct']), 1),
                "formula": "YoY_Pct (largest year-over-year faller)"
            })

    # Cap at 25 facts, most important ones were added first
    facts = facts[:25]

    print(json.dumps(facts))


if __name__ == "__main__":
    main()
